body:
The buildPartitions function returns all rows in a single partition regardless of the partitionBy columns. This defeats the purpose of partitioning and will produce incorrect results.
```suggestion
	// Create a map to group row indices by unique partition keys
	partitionMap := make(map[string][]int)

	// Iterate over each row
	for i := 0; i < dataLength; i++ {
		// Build the partition key by concatenating values from partitionBy columns
		var keyParts []string
		for _, colName := range partitionBy {
			col, exists := columns[colName]
			if !exists {
				return nil, fmt.Errorf("column %s not found", colName)
			}
			keyParts = append(keyParts, fmt.Sprintf("%v", col.Value(i)))
		}
		key := fmt.Sprintf("%v", keyParts)

		// Add the row index to the corresponding partition
		partitionMap[key] = append(partitionMap[key], i)
	}

	// Convert the map to a slice of partitions
	partitions := make([][]int, 0, len(partitionMap))
	for _, indices := range partitionMap {
		partitions = append(partitions, indices)
	}

	return partitions, nil
```

