+    ...context
+  });
+};
+
+export const logInfo = (
+  message: string,
+  context?: {
+    requestId?: string;
+    userId?: string;
+    component?: string;
+    operation?: string;
+    metadata?: Record<string, any>;
+  }
+) => {
