+  });
+};
+
+export const logAuth = (
+  operation: LogOperation,
+  message: string,
+  context?: {
+    requestId?: string;
+    userId?: string;
+    metadata?: Record<string, any>;
+  }
+) => {
+  logInfo(message, {
