body:
[nitpick] Consider refactoring the system health score calculation logic into smaller, well-named helper functions to improve readability and ease future maintenance.
```suggestion
    // 各ペナルティを計算してスコアを減点
    score -= this.calculateFailureRatePenalty(authStats.failureRate);
    score -= this.calculateErrorRatePenalty(apiStats.errorRate);
    score -= this.calculateResponseTimePenalty(apiStats.responseTimeStats.p95);

    return Math.max(0, Math.round(score));
  }

  private calculateFailureRatePenalty(failureRate: number): number {
    return Math.min(30, failureRate * 100);
  }

  private calculateErrorRatePenalty(errorRate: number): number {
    return Math.min(40, errorRate * 200);
  }

  private calculateResponseTimePenalty(p95: number): number {
    const p95Penalty = Math.max(0, (p95 - 1000) / 100);
    return Math.min(30, p95Penalty);
  }
```

