> Carefully review the code before committing. Ensure that it accurately replaces the highlighted code, contains no missing lines, and has no issues with indentation. Thoroughly test & benchmark the code to ensure it meets the requirements.

```suggestion
  private parseYarnLock(content: string): Map<string, string> {
    const packages = new Map<string, string>();
    const lines = content.split('\n');
    let currentPackage: string | null = null;

    for (const line of lines) {
      const trimmed = line.trim();

      // パッケージ名の行をチェック
      if (trimmed.endsWith(':') && !trimmed.startsWith(' ')) {
        // "package-name@version:" or "@scope/package@version:" の形式
        const match = trimmed.match(/^(.+?)@[^@]+:$/);
        if (match) {
          currentPackage = match[1].replace(/^"|"$/g, '');
        }
      }

      // バージョン情報の行をチェック
      if (currentPackage && trimmed.startsWith('version ')) {
        const version = trimmed.replace('version ', '').replace(/"/g, '');
        packages.set(currentPackage, version);
        currentPackage = null;
      }
    }

    return packages;
  }
```

</details>

<!-- suggestion_end -->

