+func (m listModel) Init() tea.Cmd {
+	return m.LoadItems("videos")
+}
+
+func (m listModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
+	switch msg := msg.(type) {
+	case tea.KeyMsg:
+		switch msg.String() {
+		case "enter":
+			if item, ok := m.list.SelectedItem().(listItem); ok {
+				m.selectedID = item.id
+			}
+		case "n":
+			// Create new item
+		case "esc":
+			m.selectedID = ""
+		}
+	case loadingMsg:
+		m.loading = true
+		return m, nil
+	case itemsLoadedMsg:
+		m.loading = false
+		m.list.Title = fmt.Sprintf("%d items", len(msg.items))
+		cmd := m.list.SetItems(msg.items)
+		return m, cmd
+	}
+
+	var cmd tea.Cmd
+	m.list, cmd = m.list.Update(msg)
+	return m, cmd
+}
+
+func (m listModel) View() string {
+	if m.loading {
+		return "\n  Loading..."
+	}
+	return m.list.View()
+}
+
+func (m *listModel) SetSize(width, height int) {
+	m.list.SetWidth(width)
+	m.list.SetHeight(height)
+}
+
+type itemsLoadedMsg struct {
+	items []list.Item
+}
+
+type loadingMsg struct{}
+
+func (m listModel) LoadItems(contentType string) tea.Cmd {
+	return tea.Batch(
+		func() tea.Msg { return loadingMsg{} },
+		func() tea.Msg {
+			client := newGraphQLClient()
+			
+			switch contentType {
+		case "videos":
+			videos, err := client.getLatestVideos(20)
+			if err != nil {
+				// Fallback to database
+				dbClient := newDatabaseClient()
+				videos, err = dbClient.getAllVideosFromDB()
+				if err != nil {
+					return nil
+				}
+			}
+			items := make([]list.Item, len(videos))
+			for i, v := range videos {
+				desc := v.Description
+				if len(desc) > 80 {
+					desc = desc[:77] + "..."
+				}
+				items[i] = listItem{
+					id:          v.ID,
+					title:       v.Title,
+					description: desc,
+				}
+			}
+			return itemsLoadedMsg{items: items}
+			
+		case "shows":
+			shows, err := client.getAllShows()
+			if err != nil {
+				// Fallback to database
+				dbClient := newDatabaseClient()
+				shows, err = dbClient.getAllShowsFromDB()
+				if err != nil {
+					items := []list.Item{
+						listItem{
+							id:          "error",
+							title:       "Error loading shows",
+							description: fmt.Sprintf("Error: %v", err),
+						},
+					}
+					return itemsLoadedMsg{items: items}
+				}
+			}
+			items := make([]list.Item, len(shows))
+			for i, s := range shows {
+				items[i] = listItem{
+					id:          s.ID,
+					title:       s.Name,
+					description: fmt.Sprintf("%d episodes", len(s.Episodes)),
+				}
+			}
+			return itemsLoadedMsg{items: items}
+			
+		case "people":
+			// Try GraphQL first (from video guests)
+			people, err := client.getPeopleFromVideos()
+			if err != nil || len(people) == 0 {
+				// Fallback to database
+				dbClient := newDatabaseClient()
+				people, err = dbClient.getAllPeople()
+				if err != nil {
+					items := []list.Item{
+						listItem{
+							id:          "error",
+							title:       "Error loading people",
+							description: fmt.Sprintf("Database error: %v", err),
+						},
+					}
+					return itemsLoadedMsg{items: items}
+				}
+			}
+			items := make([]list.Item, len(people))
+			for i, p := range people {
+				bio := p.Biography
+				if len(bio) > 80 {
+					bio = bio[:77] + "..."
+				}
+				items[i] = listItem{
+					id:          p.ID,
+					title:       fmt.Sprintf("%s %s", p.Forename, p.Surname),
+					description: bio,
+				}
+			}
+			return itemsLoadedMsg{items: items}
+			
+		case "technologies":
+			techs, err := client.getTechnologies()
+			if err != nil {
+				return nil
+			}
+			items := make([]list.Item, len(techs))
+			for i, t := range techs {
+				desc := t.Description
+				if len(desc) > 80 {
+					desc = desc[:77] + "..."
+				}
+				items[i] = listItem{
+					id:          t.ID,
+					title:       t.Name,
+					description: desc,
+				}
+			}
+			return itemsLoadedMsg{items: items}
+			
+		case "episodes":
+			episodes, err := client.getAllEpisodes()
+			if err != nil {
+				return nil
+			}
+			items := make([]list.Item, len(episodes))
+			for i, e := range episodes {
+				items[i] = listItem{
+					id:          e.ID,
+					title:       e.Code,
+					description: fmt.Sprintf("Episode %s", e.Code),
+				}
+			}
+			return itemsLoadedMsg{items: items}
+		}
+		
+		return itemsLoadedMsg{items: []list.Item{}}
+		},
+	)
+}
