_⚠️ Potential issue_

**Improve type safety by properly typing window properties.**

The code uses `any` type casting to access `window.statusManager` and `window.vscode`, which bypasses TypeScript's type safety.

Add proper type declarations:

```diff
+// At the top of the file, add:
+interface WindowWithExtensions extends Window {
+  statusManager?: {
+    showStatus: (message: string, type: string) => void;
+  };
+  vscode?: {
+    postMessage: (message: any) => void;
+  };
+}
+
+declare const window: WindowWithExtensions;

 private showUserError(message: string): void {
   // ステータスマネージャーが利用可能な場合は使用
-  if (typeof window !== 'undefined' && (window as any).statusManager) {
-    (window as any).statusManager.showStatus(message, 'error');
+  if (typeof window !== 'undefined' && window.statusManager) {
+    window.statusManager.showStatus(message, 'error');
   } else {
     // フォールバック：コンソールログのみ
     console.warn('Status manager not available, error message:', message);
   }
 }

 private reportToExtension(errorInfo: {
   type: string;
   message: string;
   context: string;
   stack?: string;
 }): void {
   try {
-    if (typeof window !== 'undefined' && (window as any).vscode) {
-      (window as any).vscode.postMessage({
+    if (typeof window !== 'undefined' && window.vscode) {
+      window.vscode.postMessage({
         command: 'error',
         ...errorInfo,
         timestamp: Date.now(),
       });
     }
   } catch (reportError) {
     console.error('Failed to report error to extension:', reportError);
   }
 }
```

