+    try {
+      return fn();
+    } catch (error) {
+      ErrorHandler.getInstance().handleGenericError(error as Error, context);
+      return fallback;
+    }
+  }
+
+  /**
+   * 非同期関数の安全な実行ラッパー
+   */
+  public static async safeExecuteAsync<T>(
+    fn: () => Promise<T>,
+    context: string,
+    fallback?: T
+  ): Promise<T | undefined> {
+    try {
+      return await fn();
+    } catch (error) {
+      ErrorHandler.getInstance().handleGenericError(error as Error, context);
+      return fallback;
+    }
+  }
+}
