_🛠️ Refactor suggestion_

**Eliminate code duplication between confidence processing functions**

The confidence validation and processing logic is duplicated between `confidencePercent` and `getConfidenceClass` functions. This violates the DRY principle and creates maintenance overhead.



Extract the common logic into a shared function:

```diff
+  // Shared confidence processing logic
+  function processConfidence(confidence: number): number {
+    // Validate input is a number
+    if (typeof confidence !== 'number' || isNaN(confidence)) {
+      return 0;
+    }
+
+    // Determine if it's decimal (0-1) or percentage (0-100) format
+    const isDecimal = confidence <= 1;
+    const percent = isDecimal ? confidence * 100 : confidence;
+
+    // Clamp to valid range (0-100)
+    return Math.max(0, Math.min(100, percent));
+  }
+
   const confidencePercent = $derived(() => {
-    // Validate input is a number
-    if (typeof confidence !== 'number' || isNaN(confidence)) {
-      return 0;
-    }
-
-    // Determine if it's decimal (0-1) or percentage (0-100) format
-    const isDecimal = confidence <= 1;
-    const percent = isDecimal ? confidence * 100 : confidence;
-
-    // Clamp to valid range (0-100)
-    const clampedPercent = Math.max(0, Math.min(100, percent));
-
-    return Math.round(clampedPercent);
+    return Math.round(processConfidence(confidence));
   });

   function getConfidenceClass(confidence: number): string {
-    // Validate input is a number
-    if (typeof confidence !== 'number' || isNaN(confidence)) {
-      return 'confidence-low';
-    }
-
-    // Determine if it's decimal (0-1) or percentage (0-100) format
-    const isDecimal = confidence <= 1;
-    const percent = isDecimal ? confidence * 100 : confidence;
-
-    // Clamp to valid range (0-100)
-    const clampedPercent = Math.max(0, Math.min(100, percent));
+    const clampedPercent = processConfidence(confidence);

     if (clampedPercent >= 70) return 'confidence-high';
     if (clampedPercent >= 40) return 'confidence-medium';
     return 'confidence-low';
   }
```

<!-- suggestion_start -->

<details>
<summary>📝 Committable suggestion</summary>

> ‼️ **IMPORTANT**
> Carefully review the code before committing. Ensure that it accurately replaces the highlighted code, contains no missing lines, and has no issues with indentation. Thoroughly test & benchmark the code to ensure it meets the requirements.

```suggestion
  // Shared confidence processing logic
  function processConfidence(confidence: number): number {
    // Validate input is a number
    if (typeof confidence !== 'number' || isNaN(confidence)) {
      return 0;
    }

    // Determine if it's decimal (0-1) or percentage (0-100) format
    const isDecimal = confidence <= 1;
    const percent = isDecimal ? confidence * 100 : confidence;

    // Clamp to valid range (0-100)
    return Math.max(0, Math.min(100, percent));
  }

  const confidencePercent = $derived(() => {
    return Math.round(processConfidence(confidence));
  });
  const isMaxConfidence = $derived(confidencePercent() === 100);

  function getConfidenceClass(confidence: number): string {
    const clampedPercent = processConfidence(confidence);

    if (clampedPercent >= 70) return 'confidence-high';
    if (clampedPercent >= 40) return 'confidence-medium';
    return 'confidence-low';
  }
```

</details>

