body:
![medium](https://www.gstatic.com/codereviewagent/medium-priority.svg)

This logic for determining if a statement should be kept can be made more idiomatic. Instead of a `match` with a guard for `assign.targets.len() == 1`, you can match on `Stmt::Assign` and then use a slice pattern `if let [Expr::Attribute(attr)] = assign.targets.as_slice()` to handle the single-target case. This is a bit more explicit and avoids the guard. The nested `if let` statements improve readability by making the structure of the data being matched more explicit.

```rust
            let should_keep = match &stmt {
                Stmt::Assign(assign) => {
                    if let [Expr::Attribute(attr)] = assign.targets.as_slice() {
                        if let Expr::Name(base) = attr.value.as_ref() {
                            // Only deduplicate special namespace attributes like __all__,
                            // __version__, etc. These are the ones that
                            // get duplicated when processing parent/child modules
                            if attr.attr.as_str().starts_with("__")
                                && attr.attr.as_str().ends_with("__")
                            {
                                let key = (base.id.to_string(), attr.attr.to_string());
                                // Only keep if we haven't seen this assignment before
                                seen_assignments.insert(key)
                            } else {
                                // Don't deduplicate regular attributes
                                true
                            }
                        } else {
                            true
                        }
                    } else {
                        true
                    }
                }
                _ => true,
            };
```

