+import type { RankingItem } from '@/types/ranking'
+
+const SNAPSHOT_API_URL = 'https://snapshot.search.nicovideo.jp/api/v2/snapshot/video/contents/search'
+const USER_AGENT = 'nico-ranking-app/1.0'
