+}
+
+// Convert space-separated tag string to array
+function parseTagString(tagString: string | undefined): string[] {
+  if (!tagString || typeof tagString !== 'string') {
+    return []
+  }
+  
+  return tagString
+    .split(' ')
+    .map(tag => tag.trim())
