+    compareFn?: (a: T, b: T) => number
+  ): number {
+    const compare = compareFn || ((a, b) => a < b ? -1 : a > b ? 1 : 0);
+    
+    let left = 0;
+    let right = arr.length - 1;
+    
+    while (left <= right) {
+      const mid = Math.floor((left + right) / 2);
+      const comparison = compare(arr[mid], target);
+      
+      if (comparison === 0) {
+        return mid;
+      } else if (comparison < 0) {
+        left = mid + 1;
+      } else {
+        right = mid - 1;
+      }
+    }
+    
+    return -1;
+  }
