+    if (!accountStakedBy.data || !selectedAccount?.address) {
+      return BigInt(0);
+    }
+
+    const stake = accountStakedBy.data.get(
+      selectedAccount.address as SS58Address,
+    );
+
+    return formatToken(stake ?? 0n);
+  }, [accountStakedBy, selectedAccount?.address]);
+
