+      const chunk = items.slice(i, i + chunkSize);
+      
+      chunk.forEach(processor);
+      
+      // 次のチャンクまで待機
+      if (i + chunkSize < items.length && delay > 0) {
+        await new Promise(resolve => setTimeout(resolve, delay));
+      }
+    }
+  }
+
+  /**
+   * プロミスの並列処理（制限付き）
+   */
+  public static async processInParallel<T, R>(
+    items: T[],
+    processor: (item: T) => Promise<R>,
+    concurrency = 3
+  ): Promise<R[]> {
+    const results: R[] = [];
+    const executing: Promise<void>[] = [];
+    
+    for (const item of items) {
+      const promise = processor(item).then(result => {
+        results.push(result);
+      });
+      
+      executing.push(promise);
+      
+      if (executing.length >= concurrency) {
+        await Promise.race(executing);
+        executing.splice(executing.findIndex(p => p === promise), 1);
+      }
+    }
+    
+    await Promise.all(executing);
+    return results;
+  }
+
+  /**
+   * オブジェクトのディープクローン（パフォーマンス重視）
+   */
+  public static deepClone<T>(obj: T): T {
+    if (obj === null || typeof obj !== 'object') {
+      return obj;
+    }
+    
+    if (obj instanceof Date) {
+      return new Date(obj.getTime()) as unknown as T;
+    }
+    
+    if (obj instanceof Array) {
+      return obj.map(item => this.deepClone(item)) as unknown as T;
+    }
+    
+    if (typeof obj === 'object') {
+      const cloned = {} as T;
+      Object.keys(obj).forEach(key => {
+        (cloned as any)[key] = this.deepClone((obj as any)[key]);
+      });
+      return cloned;
+    }
+    
+    return obj;
+  }
+
+  /**
+   * 配列の高速検索（バイナリサーチ）
+   */
+  public static binarySearch<T>(
+    arr: T[],
+    target: T,
+    compareFn?: (a: T, b: T) => number
+  ): number {
+    const compare = compareFn || ((a, b) => a < b ? -1 : a > b ? 1 : 0);
+    
+    let left = 0;
+    let right = arr.length - 1;
+    
+    while (left <= right) {
+      const mid = Math.floor((left + right) / 2);
+      const comparison = compare(arr[mid], target);
+      
+      if (comparison === 0) {
+        return mid;
+      } else if (comparison < 0) {
+        left = mid + 1;
+      } else {
+        right = mid - 1;
+      }
+    }
+    
+    return -1;
+  }
+}
