body:
The security configuration allows all requests to /api/dev/** endpoints to be publicly accessible. In production environments, these development endpoints should be restricted or disabled to prevent information disclosure.
```suggestion
import org.springframework.core.env.Environment;
import java.util.List;

@Configuration
@EnableWebSecurity
public class SecurityConfiguration {

    private final String activeProfile;

    public SecurityConfiguration(org.springframework.core.env.Environment environment) {
        this.activeProfile = environment.getProperty("spring.profiles.active", "default");
    }

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .csrf(AbstractHttpConfigurer::disable)
            .cors(cors -> cors.configurationSource(corsConfigurationSource()))
            .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
            .authorizeHttpRequests(auth -> {
                // Public endpoints
                auth.requestMatchers(
                    "/actuator/health",
                    "/actuator/info",
                    "/v3/api-docs/**",
                    "/swagger-ui/**",
                    "/swagger-ui.html"
                ).permitAll();

                // Development endpoints (restricted in production)
                if ("dev".equals(activeProfile)) {
                    auth.requestMatchers("/api/dev/**").permitAll();
                } else {
                    auth.requestMatchers("/api/dev/**").denyAll();
                }

                // All other endpoints require authentication
                auth.anyRequest().authenticated();
            });
```

