+  const submitResult = form.submit();
+  console.log('✓ Form submission result:', submitResult);
+  console.log('');
+
+  console.log('All tests completed successfully!');
+}
+
+// Run tests
+try {
+  runTests();
+} catch (error) {
+  console.error('Test failed:', error);
+  process.exit(1);
+}
