+    void* mapped_at = mmap(0, PAGE_SIZE, PROT_READ, MAP_FILE | MAP_SHARED, fd, 0);
+    
+    close(fd);
+    
+    if (mapped_at == MAP_FAILED) {
+        *error_code = errno;
+        printf("[vmBehavior] mmap failed: %s\n", strerror(errno));
+        return NULL;
+    }
+    
+    return mapped_at;
