+    if (kr != KERN_SUCCESS) {
+        printf("[vmBehavior] failed to set VM_BEHAVIOR_ZERO_WIRED_PAGES: %s\n", mach_error_string(kr));
+        munmap(page, PAGE_SIZE);
+        return VMBEHAVIOR_ERROR_VM_SET;
+    }
+    
+    printf("[vmBehavior] set VM_BEHAVIOR_ZERO_WIRED_PAGES\n");
+    
+    int mlock_err = mlock(page, PAGE_SIZE);
+    if (mlock_err != 0) {
+        printf("[vmBehavior] mlock failed: %s\n", strerror(errno));
+        munmap(page, PAGE_SIZE);
+        return VMBEHAVIOR_ERROR_MLOCK;
+    }
+    printf("[vmBehavior] mlock success\n");
+    
+    kr = vm_deallocate(mach_task_self(),
