+        
+        private void CalculatePivots()
+        {
+            if (CurrentBars[1] < PivotStrength * 2) return;
+            
+            int currentBar = CurrentBars[1];
+            double currentHigh = Highs[1][0];
+            double currentLow = Lows[1][0];
+            DateTime currentTime = Times[1][0];
