+{questions}
+
+答えられた質問の番号をJSON形式で返してください:
+{{
+  "answered": [回答された質問の番号（0から始まる）]
+}}
+`);
+
+    const chain = RunnableSequence.from([
+      prompt,
+      this.llm,
+      new StringOutputParser(),
+    ]);
+
