+            'bing.com/chat',
+            'character.ai',
+            'replika.ai'
+        ];
+        
+        const isAISite = aiSites.some(site => tab.url.includes(site));
+        
+        if (isAISite) {
+            // Injeta CSS para destacar a extensão quando em sites de IA
