    // Check file extension
    const allowedExtensions = ['.jpg', '.jpeg', '.png', '.gif', '.webp', '.txt', '.pdf', '.json'];
    const fileName = file.name.toLowerCase();
    const fileExtension = fileName.substring(fileName.lastIndexOf('.'));

    if (!allowedExtensions.includes(fileExtension)) {
      return { isValid: false, error: 'File extension not allowed' };
    }

    // Check for double extensions
    const allExtensions = fileName.match(/\.[^.]+/g) || [];
    for (const ext of allExtensions) {
      if (!allowedExtensions.includes(ext) && ext !== fileExtension) {
        return { isValid: false, error: 'Multiple extensions detected' };
      }
    }
```

