+		c.parseStatusBody(body, status)
+		return status, nil
+	case types.StatusNotFound:
+		return nil, fmt.Errorf("test not found or not ready")
+	}
+
+	if statusCode < 200 || statusCode > 299 {
+		return nil, c.parseAPIError(statusCode, body)
