+      expect(result.data.flag).toBe('');
+    }
+  });

body:
![medium](https://www.gstatic.com/codereviewagent/medium-priority.svg)

The `processText` function has duplicated logic for handling letters and numbers. This can be simplified by extracting the common parts into a separate function or by using a single conditional to handle both cases.

```typescript
function processChar(char: string, encode: boolean, charCount: number, result: string): { newResult: string, newCharCount: number } {
  let newResult = result;
  let newCharCount = charCount;

  if (encode && newCharCount % 5 === 0 && newCharCount > 0) {
    newResult += ' ';
  }

  newResult += char;
  newCharCount++;

  return { newResult, newCharCount };
}

function processText(text: string, encode: boolean): string {
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const reverse = 'zyxwvutsrqponmlkjihgfedcba';
  let result = '';
  let charCount = 0;

  for (const char of text.toLowerCase()) {
    if (char >= 'a' && char <= 'z') {
      const index = alphabet.indexOf(char);
      const { newResult, newCharCount } = processChar(reverse[index], encode, charCount, result);
      result = newResult;
      charCount = newCharCount;
    } else if (char >= '0' && char <= '9') {
      const { newResult, newCharCount } = processChar(char, encode, charCount, result);
      result = newResult;
      charCount = newCharCount;
    }
  }

  return result.trim();
}
```

