+  getUserRoles: vi.fn(),
+  getListOfMembers: vi.fn(),
+  getAPIQueueStats: vi.fn(),
+}));
+
+vi.mock('../../services/auth.js', () => ({
+  getToken: vi.fn(),
+}));
