+import DateTimePicker from "@react-native-community/datetimepicker";
+import { router, Stack, useLocalSearchParams } from "expo-router";
+import { useUser } from "@clerk/clerk-expo";
+import { zodResolver } from "@hookform/resolvers/zod";
+import { Calendar, Clock, Image as ImageIcon, Plus } from "lucide-react-native";
+import { Controller, useForm } from "react-hook-form";
+import { toast } from "sonner-native";
+import { z } from "zod";
+
+import { Button } from "~/components/Button";
+import LoadingSpinner from "~/components/LoadingSpinner";
+import { api } from "~/utils/api";
+
+// Define the form schema based on the event update schema
+const formSchema = z.object({
+  event: z.object({
+    name: z.string().min(1, "Event name is required"),
+    description: z.string().optional(),
+    startDate: z.string().min(1, "Start date is required"),
+    endDate: z.string().min(1, "End date is required"),
+    startTime: z.string().optional(),
+    endTime: z.string().optional(),
+    timeZone: z.string().optional(),
+    location: z.string().optional(),
+    images: z.array(z.string()).optional(),
+  }),
+  eventMetadata: z.object({
+    eventType: z.string().optional(),
+    eventCategory: z.string().optional(),
+    priceType: z.string().optional(),
+    price: z.string().optional(),
+    ageRestriction: z.string().optional(),
+    performers: z.string().optional(),
+    accessibility: z.string().optional(),
+  }),
+  comment: z.string().optional(),
+  lists: z
+    .array(
+      z.object({
+        label: z.string(),
+        value: z.string(),
+      }),
+    )
+    .optional(),
+  visibility: z.string().optional(),
+});
+
+type FormData = z.infer<typeof formSchema>;
+
+export default function EditEventScreen() {
+  const { id } = useLocalSearchParams<{ id: string }>();
+  const insets = useSafeAreaInsets();
+  const { user: currentUser } = useUser();
+  const [isSubmitting, setIsSubmitting] = useState(false);
+  const [selectedImage, setSelectedImage] = useState<string | null>(null);
+
+  // Fetch the event data
+  const eventQuery = api.event.get.useQuery(
+    { eventId: id || "" },
+    {
+      enabled: Boolean(id),
+    },
+  );
+
+  // Update event mutation
+  const updateEventMutation = api.event.update.useMutation({
+    onMutate: () => setIsSubmitting(true),
+    onSettled: () => setIsSubmitting(false),
+    onSuccess: () => {
+      toast.success("Event updated successfully");
+      router.back();
+    },
+    onError: (error) => {
+      toast.error("Failed to update event", {
+        description: error.message,
+      });
+    },
+  });
+
+  const {
+    control,
+    handleSubmit,
+    formState: { errors, isDirty, isValid },
+    reset,
+  } = useForm<FormData>({
+    resolver: zodResolver(formSchema),
+    mode: "onBlur",
+  });
+
+  // Initialize form with event data when it's loaded
+  useEffect(() => {
+    if (eventQuery.data) {
+      const event = eventQuery.data;
+      const eventData = event.event as {
+        name?: string;
+        description?: string;
+        startDate?: string;
+        endDate?: string;
+        startTime?: string;
+        endTime?: string;
+        timeZone?: string;
+        location?: string;
+        images?: string[];
+      };
+
+      const eventMetadata =
+        (event.eventMetadata as {
+          eventType?: string;
+          eventCategory?: string;
+          priceType?: string;
+          price?: string;
+          ageRestriction?: string;
+          performers?: string;
+          accessibility?: string[];
+        }) || {};
+
+      reset({
+        event: {
+          name: eventData.name || "",
+          description: eventData.description || "",
+          startDate: eventData.startDate || "",
+          endDate: eventData.endDate || "",
+          startTime: eventData.startTime || "",
+          endTime: eventData.endTime || "",
+          timeZone: eventData.timeZone || "",
+          location: eventData.location || "",
+          images: eventData.images || [],
+        },
+        eventMetadata: {
+          eventType: eventMetadata.eventType || "",
+          eventCategory: eventMetadata.eventCategory || "",
+          priceType: eventMetadata.priceType || "",
+          price: eventMetadata.price || "",
+          ageRestriction: eventMetadata.ageRestriction || "",
+          performers: eventMetadata.performers || "",
+          accessibility: Array.isArray(eventMetadata.accessibility)
+            ? eventMetadata.accessibility.join(", ")
+            : "",
+        },
+        comment: "",
+        lists: [],
+        visibility: event.visibility || "",
+      });
+
+      // Set the selected image if there are images
+      if (
+        eventData.images &&
+        eventData.images.length > 0 &&
+        eventData.images[0]
+      ) {
+        setSelectedImage(eventData.images[0]);
+      }
+    }
+  }, [eventQuery.data, reset, setSelectedImage]);
+
+  // Handle image picking
+  const pickImage = async () => {
+    try {
+      // Request permissions
+      const { status } =
+        await ImagePicker.requestMediaLibraryPermissionsAsync();
+
+      if (status !== "granted") {
+        toast.error("Permission to access media library is required");
+        return;
+      }
+
+      // Launch image picker
+      const result = await ImagePicker.launchImageLibraryAsync({
+        mediaTypes: ImagePicker.MediaTypeOptions.Images,
+        allowsEditing: true,
+        aspect: [4, 3],
+        quality: 0.8,
+      });
+
+      if (
+        !result.canceled &&
+        result.assets &&
+        result.assets.length > 0 &&
+        result.assets[0]?.uri
+      ) {
+        setSelectedImage(result.assets[0].uri);
+      }
+    } catch (error) {
+      console.error("Error picking image:", error);
+      toast.error("Failed to pick image");
+    }
+  };
+
+  // Handle form submission
+  const onSubmit = useCallback(
+    async (data: FormData) => {
+      if (!id) return;
+
+      const loadingToastId = toast.loading("Updating event...");
+      try {
+        // Format accessibility as an array if it's a string
+        const accessibilityArray = data.eventMetadata.accessibility
+          ? data.eventMetadata.accessibility
+              .split(",")
+              .map((item) => item.trim())
+          : [];
+
+        // Format performers as an array if it's a string
+        const performersArray = data.eventMetadata.performers
+          ? data.eventMetadata.performers.split(",").map((item) => item.trim())
+          : [];
+
+        // Prepare the event data in the format expected by the API
+        const updatedData = {
+          id,
+          event: {
+            ...data.event,
+            images: selectedImage ? [selectedImage] : [],
+          },
+          eventMetadata: {
+            ...data.eventMetadata,
+            accessibility: accessibilityArray,
+            performers: performersArray,
+          },
+          comment: data.comment || "",
+          lists: [{}] as Record<string, string>[],
+          visibility:
+            data.visibility === "public" || data.visibility === "private"
+              ? (data.visibility as "public" | "private")
+              : ("public" as const),
+        };
+
+        await updateEventMutation.mutateAsync(updatedData);
+        toast.dismiss(loadingToastId);
+      } catch (error) {
+        console.error("Error updating event:", error);
+        toast.dismiss(loadingToastId);
+      }
+    },
+    [id, updateEventMutation, selectedImage],
+  );
+
+  // Early return if the 'id' is missing or invalid
+  if (!id || typeof id

