body:
Echoing the raw URL (which may include credentials) in error messages can leak sensitive information. Mask or omit credential portions before including the URL in exceptions.
```suggestion
  const sanitizeUrl = (rawUrl: string): string => {
    try {
      const parsedUrl = new URL(rawUrl);
      if (parsedUrl.username || parsedUrl.password) {
        parsedUrl.username = '***';
        parsedUrl.password = '***';
      }
      return parsedUrl.toString();
    } catch {
      return rawUrl; // Return the raw URL if it cannot be parsed
    }
  };

  const sanitizedUrl = sanitizeUrl(url);

  if (url.includes('--upload-pack') || url.includes('--config') || url.includes('--exec')) {
    throw new RepomixError(`Invalid repository URL. URL contains potentially dangerous parameters: ${sanitizedUrl}`);
  }

  // Check if the URL starts with git@ or https://
  if (!(url.startsWith('git@') || url.startsWith('https://'))) {
    throw new RepomixError(`Invalid remote: ${sanitizedUrl}`);
```

