logic: Missing cleanup for shareIntent effect. Should return cleanup function to handle unmounting and prevent memory leaks.

```suggestion
  useEffect(() => {
    let mounted = true;

    // Handle shared content
    const handleSharedContent = async () => {
      if (shareIntent && mounted) {
        try {
          if (shareIntent.files && shareIntent.files.length > 0) {
            // Handle shared files
            const file = shareIntent.files[0];
            await uploadFile({
              uri: file.path,
              mimeType: file.mimeType,
              name: file.fileName,
            });
          } else if (shareIntent.text) {
            // Handle shared text (could save as markdown or process differently)
            const textFile = {
              uri: `${FileSystem.cacheDirectory}shared-text-${Date.now()}.md`,
              mimeType: 'text/markdown',
              name: 'shared-text.md',
              text: shareIntent.text
            };

            await uploadFile(textFile);
          }
        } catch (error) {
          console.error('Error handling shared content:', error);
          if (mounted) {
            setUploadResult({
              status: 'error',
              error: error instanceof Error ? error.message : 'Failed to process shared content'
            });
            setStatus('error');
          }
        }
      }
    };

    handleSharedContent();
    return () => { mounted = false; };
  }, [shareIntent]);
