+	{
+	struct curl_resp *r = (struct curl_resp*)data;
+	size_t tot = size * nmemb;
+	char *tmp = realloc(r->buf, r->len + tot + 1);
+	if(tmp == NULL)
+		return 0;
+	r->buf = tmp;
+	memcpy(r->buf + r->len, ptr, tot);
+	r->len += tot;
+	r->buf[r->len] = '\0';
