+            $title = $matches[2][$i][0];
+            $offset = $match[1];
+            $end = $offset + strlen($match[0]);
+            if (isset($markdown[$end]) && $markdown[$end] === "\r") {
+                $end++;
+            }
+            if (isset($markdown[$end]) && $markdown[$end] === "\n") {
+                $end++;
+            }
+            $baseAnchor = preg_replace('/[ %\/#]/', '-', strtolower($title));
+            $a = $baseAnchor;
+            $c = 2;
+            while (in_array($a, $anchors, true)) {
+                $a = $baseAnchor . '-' . $c++;
+            }
+            $anchors[] = $a;
+            $headings[] = [
+                'level' => $level,
+                'anchor' => $a,
+                'start' => $offset,
+                'after' => $end
+            ];

