-						const connectedNode = data.nodes.find(
-							(node) => node.id === connection.inputNode.id,
-						);
-						if (connectedNode === undefined) {
-							continue;
-						}
-						switch (connectedNode.content.type) {
-							case "textGeneration": {
-								updateNodeData(connectedNode, {
-									inputs: connectedNode.inputs.filter(
-										(input) => input.id !== connection.inputId,
-									),
-								});
-							}
-						}
-					}
+					// Clean up connections where this node is involved
+					const connectionsToDelete = data.connections.filter(
+						(conn) => conn.outputNode.id === nodeChange.id || conn.inputNode.id === nodeChange.id
+					);
+					
+					for (const connection of connectionsToDelete) {
+						deleteConnection(connection.id);
+						
+						// Update input node if it's a non-action operation node
+						const inputNode = data.nodes.find(
+							(node) => node.id === connection.inputNode.id,
+						);
+						if (
+							inputNode &&
+							inputNode.type === "operation" &&
+							inputNode.content.type !== "action"
+						) {
+							updateNodeData(inputNode, {
+								inputs: inputNode.inputs.filter(
+									(input) => input.id !== connection.inputId,
+								),
+							});
+						}
+					}
					await deleteNode(nodeChange.id);
					break;
				}
			}
		}),
	);
}}
```

