+use clap::Parser;
+use once_cell::sync::Lazy;
+use regex::Regex;
+use reqwest::header::{ACCEPT, AUTHORIZATION, HeaderMap, USER_AGENT};
+use serde::Deserialize;
+use serde_json::json;
+use std::{env, fs, path::Path};
+use termimad::MadSkin;
+use thiserror::Error;
+use url::Url;
+
+#[derive(Parser)]
+#[command(name = "vk", about = "View Komments - show unresolved PR comments")]
+struct Args {
+    /// Pull request URL or number
+    reference: String,
+}
+
+#[derive(Debug, Clone)]
+struct RepoInfo {
+    owner: String,
+    name: String,
+}
+
+#[derive(Error, Debug)]
+enum VkError {
+    #[error("unable to determine repository")]
+    RepoNotFound,
+    #[error("request failed: {0}")]
+    Request(#[from] reqwest::Error),
+    #[error("invalid reference")]
+    InvalidRef,
+    #[error("malformed response")]
+    BadResponse,
+    #[error("API errors: {0}")]
+    ApiErrors(String),
+}
+
+static GITHUB_RE: Lazy<Regex> =
+    Lazy::new(|| Regex::new(r"github\.com[/:](?P<owner>[^/]+)/(?P<repo>[^/.]+)").unwrap());
+
+#[derive(Deserialize)]
+struct GraphQlResponse<T> {
+    data: Option<T>,
+    errors: Option<Vec<GraphQlError>>,
+}
+
+#[derive(Debug, Deserialize)]
+struct GraphQlError {
+    message: String,
+}
+
+fn handle_graphql_errors(errors: Vec<GraphQlError>) -> VkError {
+    let msg = errors
+        .into_iter()
+        .map(|e| e.message)
+        .collect::<Vec<_>>()
+        .join(", ");
+    VkError::ApiErrors(msg)
+}
+
+#[derive(Deserialize)]
+struct ThreadData {
+    repository: Repository,
+}
+
+#[derive(Deserialize)]
+struct Repository {
+    #[serde(rename = "pullRequest")]
+    pull_request: PullRequest,
+}
+
+#[derive(Deserialize)]
+struct PullRequest {
+    #[serde(rename = "reviewThreads")]
+    review_threads: ReviewThreadConnection,
+}
+
+#[derive(Deserialize)]
+struct ReviewThreadConnection {
+    nodes: Vec<ReviewThread>,
+    #[serde(rename = "pageInfo")]
+    page_info: PageInfo,
+}
+
+#[derive(Deserialize)]
+struct ReviewThread {
+    id: String,
+    comments: CommentConnection,
+}
+
+#[derive(Deserialize)]
+struct CommentConnection {
+    nodes: Vec<ReviewComment>,
+    #[serde(rename = "pageInfo")]
+    page_info: PageInfo,
+}
+
+#[derive(Deserialize)]
+struct ReviewComment {
+    body: String,
+    url: String,
+    author: Option<User>,
+}
+
+#[derive(Deserialize)]
+struct PageInfo {
+    #[serde(rename = "hasNextPage")]
+    has_next_page: bool,
+    #[serde(rename = "endCursor")]
+    end_cursor: Option<String>,
+}
+
+#[derive(Deserialize)]
+struct User {
+    login: String,
+}
+
+#[derive(Deserialize)]
+struct CommentNodeWrapper {
+    node: Option<CommentNode>,
+}
+
+#[derive(Deserialize)]
+struct CommentNode {
+    comments: CommentConnection,
+}
+
+const THREADS_QUERY: &str = r#"
+    query($owner: String!, $name: String!, $number: Int!, $cursor: String) {
+      repository(owner: $owner, name: $name) {
+        pullRequest(number: $number) {
+          reviewThreads(first: 100, after: $cursor, states: [UNRESOLVED]) {
+            nodes {
+              id
+              comments(first: 100) {
+                nodes {
+                  body
+                  url
+                  author { login }
+                }
+                pageInfo { hasNextPage endCursor }
+              }
+            }
+            pageInfo { hasNextPage endCursor }
+          }
+        }
+      }
+    }
+"#;
+
+const COMMENT_QUERY: &str = r#"
+    query($id: ID!, $cursor: String) {
+      node(id: $id) {
+        ... on PullRequestReviewThread {
+          comments(first: 100, after: $cursor) {
+            nodes {
+              body
+              url
+              author { login }
+            }
+            pageInfo { hasNextPage endCursor }
+          }
+        }
+      }
+    }
+"#;
+
+async fn paginate<T, F, Fut>(mut fetch: F) -> Result<Vec<T>, VkError>
+where
+    F: FnMut(Option<String>) -> Fut,
+    Fut: std::future::Future<Output = Result<(Vec<T>, PageInfo), VkError>>,
+{
+    let mut items = Vec::new();
+    let mut cursor = None;
+    loop {
+        let (mut page, info) = fetch(cursor.clone()).await?;
+        items.append(&mut page);
+        if !info.has_next_page {
+            break;
+        }
+        cursor = info.end_cursor;
+    }
+    Ok(items)
+}
+
+async fn fetch_comment_page(
+    client: &reqwest::Client,
+    headers: &HeaderMap,
+    id: &str,
+    cursor: Option<String>,
+) -> Result<(Vec<ReviewComment>, PageInfo), VkError> {
