![medium](https://www.gstatic.com/codereviewagent/medium-priority.svg)

Wrap the asynchronous logic within a `try...finally` block to ensure `setLoading(false)` is always called, even if an error occurs, preventing the UI from getting stuck in a loading state.

```typescript
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const { error } = await resetPassword(email);

      if (error) {
        toast({
          title: 'Reset failed',
          description: error.message,
          variant: 'destructive',
        });
      } else {
        toast({
          title: 'Check your email',
          description: 'We sent you a link to reset your password.',
        });
        navigate('/auth');
      }
    } finally {
      setLoading(false);
    }
  };
```

