[nitpick] Combining the `endmacro` of the previous macro and the `settings_row` declaration on the same line can reduce readability. Consider separating them onto two lines for clarity.
```suggestion
{%- endmacro %}
{%- macro settings_row(setting) -%}
```

The Open Graph and Twitter metadata objects contain many fields that are repeated verbatim across several pages. Consider extracting common properties (such as siteName, locale, type, images) into a shared configuration to reduce duplication and simplify future updates.
```suggestion
const sharedMetadata = {
  title: "Raspberry Pi 5 Homelab | Jacob Barkin",
  description: "How I built a powerful homelab using a Raspberry Pi 5 with Docker containers, accessible from anywhere using Tailscale and Cloudflare Tunnels.",
  images: [
    {
      url: "/images/Updated logo.png",
      width: 800,
      height: 600,
      alt: "Jacob Barkin Logo",
    },
  ],
};

export const metadata: Metadata = {
  title: sharedMetadata.title,
  description: sharedMetadata.description,
  alternates: {
    canonical: "https://jacobbarkin.com/raspberry-pi-homelab",
  },
  openGraph: {
    ...sharedMetadata,
    url: "https://jacobbarkin.com/raspberry-pi-homelab",
    siteName: "Jacob Barkin Portfolio",
    locale: "en_US",
    type: "website",
  },
