_🧹 Nitpick (assertive)_

**Consider reducing code duplication in match arms.**

The `create_unit_commands` method correctly separates unit-specific logic as suggested in past reviews. However, both match arms follow an identical pattern of record creation and command insertion.


Consider extracting the common pattern to reduce duplication:

```diff
 #[cfg(feature = "ddlog")]
 fn create_unit_commands(
     id: i64,
     unit: &UnitType,
     cmds: &mut Vec<differential_datalog::record::UpdCmd>,
 ) {
     use differential_datalog::record::{IntoRecord, RelIdentifier, UpdCmd};
     use lille_ddlog::{
         typedefs::entity_state::{Fraidiness, Meanness},
         Relations,
     };

+    fn insert_record<T: IntoRecord>(
+        cmds: &mut Vec<UpdCmd>,
+        relation: usize,
+        record: T,
+    ) {
+        cmds.push(UpdCmd::Insert(
+            RelIdentifier::RelId(relation),
+            record.into_record(),
+        ));
+    }

     match unit {
         UnitType::Civvy { fraidiness } => {
             let rec = Fraidiness {
                 entity: id,
                 factor: OrderedFloat(*fraidiness),
             };
-            cmds.push(UpdCmd::Insert(
-                RelIdentifier::RelId(Relations::entity_state_Fraidiness as usize),
-                rec.into_record(),
-            ));
+            insert_record(cmds, Relations::entity_state_Fraidiness as usize, rec);
         }
         UnitType::Baddie { meanness } => {
             let rec = Meanness {
                 entity: id,
                 factor: OrderedFloat(*meanness),
             };
-            cmds.push(UpdCmd::Insert(
-                RelIdentifier::RelId(Relations::entity_state_Meanness as usize),
-                rec.into_record(),
-            ));
+            insert_record(cmds, Relations::entity_state_Meanness as usize, rec);
         }
     }
 }
```

