+    let len = u32::from_le_bytes(data[0..4].try_into().unwrap()) as usize;
+    if data.len() < 4 + len {
+        return Err(FrameError::Truncated);
+    }
+    let payload = &data[4..4 + len];
+    serde_json::from_slice(payload).map_err(|_| FrameError::Malformed)
 }

